<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
require_once __DIR__.'/../app/bootstrap.php';
use App\Core\Database;
use App\Core\Env;
use App\Services\SocWorkspaceService;
use App\Services\NotebookService;
use App\Services\ExperimentService;
use App\Services\ModelService;
use App\Services\DeploymentService;
use App\Services\ExecutionService;
use App\Services\ValidationService;
use App\Core\AccessDeniedException;
if(Env::get('APP_ENV')!=='testing'||!str_ends_with((string)Env::get('DB_NAME'),'_test')||!in_array(Env::get('DB_HOST'),['127.0.0.1','localhost','::1'],true)){fwrite(STDERR,"REFUSED: loopback testing _test database required.\n");exit(1);}
$checks=[];$check=function(bool $ok,string $label)use(&$checks){if(!$ok)throw new RuntimeException('FAIL '.$label);$checks[]=$label;};
$reject=function(callable $op,string $class,string $label)use($check){try{$op();}catch(Throwable $e){if(!$e instanceof $class)throw $e;$check(true,$label);return;}throw new RuntimeException('FAIL accepted: '.$label);};
$pdo=Database::getConnection();$db=Database::getInstance();$marker='WORKSPACE-'.strtoupper(bin2hex(random_bytes(6)));$path=null;
try{
 $admin=(int)Database::queryOne("SELECT id FROM users WHERE role='ADMIN' AND status='ACTIVE' ORDER BY id LIMIT 1")['id'];
 $pdo->beginTransaction();
 $students=[];for($i=0;$i<2;$i++)$students[]=$db->insert('users',['role'=>'STUDENT','email'=>strtolower($marker).$i.'@example.invalid','identifier'=>$marker.$i,'full_name'=>'Workspace integration test','password_hash'=>password_hash(bin2hex(random_bytes(24)),PASSWORD_DEFAULT),'status'=>'ACTIVE']);
 [$student,$other]=$students;
 $tid=$db->insert('tickets',['ticket_code'=>$marker,'title'=>'Workspace integration ticket','created_by'=>$admin,'status'=>'ASSIGNED']);
 $db->insert('ticket_assignments',['ticket_id'=>$tid,'student_id'=>$student,'assigned_by'=>$admin]);
 $tid2=$db->insert('tickets',['ticket_code'=>$marker.'-2','title'=>'Other ticket','created_by'=>$admin,'status'=>'ASSIGNED']);
 $db->insert('ticket_assignments',['ticket_id'=>$tid2,'student_id'=>$student,'assigned_by'=>$admin]);
 $soc=new SocWorkspaceService();$nbsvc=new NotebookService();$exp=new ExperimentService();$models=new ModelService();$deploy=new DeploymentService();
 $reject(fn()=>$nbsvc->createNotebook(['title'=>'Admin should not author student code'],$admin),AccessDeniedException::class,'Administrator cannot author notebooks through student service');
 $reject(fn()=>$exp->createExperiment(['name'=>'Admin should not author experiments'],$admin),AccessDeniedException::class,'Administrator cannot author experiments through student service');
 $reject(fn()=>$models->registerModel(['model_code'=>$marker.'-ADMIN','name'=>'Admin should not author model','framework'=>'JSON'],$admin),AccessDeniedException::class,'Administrator cannot author models through student service');
 $notebook=$nbsvc->createNotebook(['title'=>'Original student notebook','ticket_id'=>$tid,'cells'=>[['source'=>"print('persisted only')",'cell_type'=>'code']]],$student);
 $reject(fn()=>$nbsvc->saveNotebook((int)$notebook['id'],['cells'=>[]],$admin,'ADMIN'),AccessDeniedException::class,'Administrator cannot overwrite original student notebook cells');
 $check($soc->notebook((int)$notebook['id'],$admin)['cells'][0]['source']==="print('persisted only')",'SOC reads actual saved student notebook cells');
 $reject(fn()=>$soc->notebook((int)$notebook['id'],$other),AccessDeniedException::class,'Student cannot use SOC notebook service');
 $experiment=$exp->createExperiment(['name'=>'Linked experiment','ticket_id'=>$tid],$student);
 $check((int)$exp->getExperiment((int)$experiment['id'],$student,'STUDENT')['student_id']===$student,'Student single-experiment endpoint has owned original record');
 $reject(fn()=>$exp->getExperiment((int)$experiment['id'],$other,'STUDENT'),AccessDeniedException::class,'Foreign experiment show denied');
 $nb2=$nbsvc->createNotebook(['title'=>'Other ticket notebook','ticket_id'=>$tid2],$student);
 $reject(fn()=>$exp->recordRun(['experiment_id'=>$experiment['id'],'run_name'=>'Wrong ticket','notebook_id'=>$nb2['id']],$student),AccessDeniedException::class,'Run notebook must belong to same ticket');
 $run=$exp->recordRun(['experiment_id'=>$experiment['id'],'run_name'=>'Reported metadata','notebook_id'=>$notebook['id'],'metrics'=>['accuracy'=>1],'status'=>'COMPLETED'],$student);
 $r=Database::queryOne('SELECT * FROM experiment_runs WHERE run_uuid=:uuid',['uuid'=>$run['run_uuid']]);
 $check($r['status']==='RECORDED'&&$r['duration_seconds']===null,'Run recording cannot claim executed timing/status');
 $reject(fn()=>$models->registerModel(['model_code'=>$marker.'-BAD','name'=>'Wrong ticket','framework'=>'JSON','ticket_id'=>$tid2,'experiment_run_id'=>$r['id']],$student),AccessDeniedException::class,'Model run must match ticket');
 $model=$models->registerModel(['model_code'=>$marker.'-M','name'=>'Original student model','framework'=>'JSON','ticket_id'=>$tid,'experiment_run_id'=>$r['id'],'metadata'=>['student_note'=>'original']],$student);$mid=(int)$model['id'];
 $check($model['versions']===[],'Registering metadata still creates no artifact version');
 $saved=$soc->updateModel($mid,['admin_label'=>'Reviewed label','admin_notes'=>'Separate administrator observation'],$admin);
 $check($saved['name']==='Original student model'&&json_decode($saved['metadata_json'],true)['student_note']==='original'&&(int)$saved['student_id']===$student,'Admin annotations preserve student authorship and original metadata');
 $check(json_decode($saved['admin_metadata_json'],true)['admin_label']==='Reviewed label'&&(int)$saved['admin_updated_by']===$admin,'Administrative metadata records actual administrator separately');
 $reject(fn()=>$soc->updateModel($mid,['name'=>'Replace authored name'],$admin),InvalidArgumentException::class,'SOC cannot silently overwrite original authored fields');
 $reject(fn()=>$soc->updateModel($mid,['admin_notes'=>'Unauthorized'],$other),AccessDeniedException::class,'Student cannot edit admin metadata');
 $check($soc->updateModel($mid,['status'=>'ARCHIVED'],$admin)['status']==='ARCHIVED','Admin archive state persists');
 $soc->updateModel($mid,['status'=>'REGISTERED'],$admin);
 $filename='workspace_contract_'.bin2hex(random_bytes(16)).'.json';$path=dirname(__DIR__).'/storage/private/models/'.$filename;
 if(!is_dir(dirname($path)))mkdir(dirname($path),0700,true);
 $file=fopen($path,'x');fwrite($file,'{"opaque_contract_bytes":true}');fclose($file);
 $vid=$db->insert('model_versions',['model_id'=>$mid,'version'=>'contract-v1','artifact_path'=>$filename,'artifact_format'=>'json','checksum_sha256'=>hash_file('sha256',$path),'file_size'=>filesize($path),'metrics'=>'{"accuracy":1}']);
 $validation=(new ValidationService())->runValidation($mid,$vid,$student);
 $check($validation['status']==='NOT_EVALUATED'&&$validation['score']===null,'Trusted quality still unavailable despite user perfect score');
 $reqData=['model_id'=>$mid,'model_version_id'=>$vid,'environment'=>'staging','replicas'=>1,'canary_percentage'=>10,'idempotency_key'=>$marker.'-REQUEST'];
 $reject(fn()=>$deploy->requestDeployment($reqData,$admin),AccessDeniedException::class,'Administrator cannot impersonate student deployment requester');
 $req=$deploy->requestDeployment($reqData,$student);$requestId=(int)$req['id'];
 $check($req['status']==='PENDING'&&$req['endpoint_url']===null&&$req['runtime_status']==='UNAVAILABLE'&&!$req['deployed'],'Request is administrative pending with no runtime endpoint');
 $auditBefore=(int)Database::queryOne("SELECT COUNT(*) AS n FROM audit_logs WHERE action='DEPLOYMENT_REQUEST_CREATED' AND resource_id=:id",['id'=>(string)$requestId])['n'];
 $notifBefore=(int)Database::queryOne("SELECT COUNT(*) AS n FROM notifications WHERE user_id=:uid",['uid'=>$admin])['n'];
 $retry=$deploy->requestDeployment($reqData,$student);
 $check((int)$retry['id']===$requestId&&(int)Database::queryOne("SELECT COUNT(*) AS n FROM audit_logs WHERE action='DEPLOYMENT_REQUEST_CREATED' AND resource_id=:id",['id'=>(string)$requestId])['n']===$auditBefore&&(int)Database::queryOne('SELECT COUNT(*) AS n FROM notifications WHERE user_id=:uid',['uid'=>$admin])['n']===$notifBefore,'Request retry has one row/event/notification');
 $reject(fn()=>$deploy->requestDeployment(array_merge($reqData,['replicas'=>2]),$student),InvalidArgumentException::class,'Idempotency key cannot reuse different request payload');
 $reject(fn()=>$deploy->reviewDeployment($requestId,'DEPLOYED',$admin),InvalidArgumentException::class,'Administrator cannot claim runtime deployment');
 $reject(fn()=>$deploy->reviewDeployment($requestId,'APPROVED',$other),AccessDeniedException::class,'Student cannot approve own or foreign deployment request');
 $approved=$deploy->reviewDeployment($requestId,'APPROVED',$admin,'Administrative approval only');
 $check($approved['status']==='APPROVED'&&$approved['endpoint_url']===null&&$approved['runtime_status']==='UNAVAILABLE','Approval remains separate from unavailable inference provider');
 $beforeReview=(int)Database::queryOne("SELECT COUNT(*) AS n FROM audit_logs WHERE action='DEPLOYMENT_REQUEST_REVIEWED' AND resource_id=:id",['id'=>(string)$requestId])['n'];
 $deploy->reviewDeployment($requestId,'APPROVED',$admin,'retry');
 $check((int)Database::queryOne("SELECT COUNT(*) AS n FROM audit_logs WHERE action='DEPLOYMENT_REQUEST_REVIEWED' AND resource_id=:id",['id'=>(string)$requestId])['n']===$beforeReview,'Repeated decision does not duplicate audit/notification');
 $reject(fn()=>$deploy->reviewDeployment($requestId,'REJECTED',$admin),InvalidArgumentException::class,'Terminal administrative decision cannot be rewritten');
 $check(count($soc->listResources('models',['student_id'=>$student],$admin))===1&&count($soc->listResources('experiments',['student_id'=>$student],$admin))===1,'SOC filters read original shared records by student');
 $jobId=$db->insert('execution_jobs',['job_uuid'=>$marker.'-JOB','notebook_id'=>$notebook['id'],'student_id'=>$student,'code_to_execute'=>'# never executed','status'=>'QUEUED']);
 $soc->cancelJob((string)$jobId,$admin);
 $job=$soc->job((string)$jobId,$admin);
 $audit=Database::queryOne("SELECT actor_id,metadata_json FROM audit_logs WHERE action='EXECUTION_JOB_CANCELLED' AND resource_id=:uuid ORDER BY id DESC LIMIT 1",['uuid'=>$job['job_uuid']]);
 $check($job['status']==='CANCELLED'&&(int)$audit['actor_id']===$admin&&json_decode($audit['metadata_json'],true)['student_id']===$student,'SOC cancellation records administrator actor without student impersonation');
 Database::execute('UPDATE ticket_assignments SET revoked_at=NOW(),revoked_by=:admin WHERE ticket_id=:tid AND student_id=:sid',['admin'=>$admin,'tid'=>$tid2,'sid'=>$student]);
 $reject(fn()=>$nbsvc->createNotebook(['title'=>'Revoked ticket notebook','ticket_id'=>$tid2],$student),AccessDeniedException::class,'Revoked ticket no longer authorizes new notebook');
 $pdo->rollBack();
 $check(Database::queryOne('SELECT id FROM users WHERE identifier=:id',['id'=>$marker.'0'])===null,'All generated workspace records rolled back');
 foreach($checks as $label)echo 'PASS '.$label.PHP_EOL;
 echo count($checks).' workspace integration checks passed on '.Env::get('DB_NAME').'; no original records deleted or modified.'.PHP_EOL;
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,$e->getMessage().PHP_EOL);exit(1);}
finally{if($path!==null&&is_file($path))unlink($path);}
